css:
.win{border-width:2px;border-radius:10px;border-color:#8a6238}
.win.focused{border-color:#5a3d1e}
.win > .bar{height:38px}
.licon .tile{border-radius:6px}
.menubar,.composer,.dock{backdrop-filter:blur(10px) saturate(1.05)}
.sd-plate{position:absolute;inset:-3%;background-size:cover;background-position:center;background-repeat:no-repeat;
  image-rendering:pixelated;opacity:0;will-change:opacity,transform;animation:sdSeason 160s infinite both}
.sd-plate.p1{opacity:1}
.sd-plate.p2{animation-delay:40s}
.sd-plate.p3{animation-delay:80s}
.sd-plate.p4{animation-delay:120s}
@keyframes sdSeason{0%{opacity:0;transform:scale(1.05) translate3d(1.2%,.6%,0);animation-timing-function:ease-in-out}
  4%{opacity:1;animation-timing-function:linear}
  25%{opacity:1;animation-timing-function:ease-in-out}
  29%{opacity:0;transform:scale(1) translate3d(-1.2%,-.6%,0)}
  100%{opacity:0;transform:scale(1) translate3d(-1.2%,-.6%,0)}}
.sd-veil{position:absolute;inset:0;
  background:radial-gradient(ellipse at 50% 45%,rgba(40,24,8,0) 45%,rgba(40,24,8,.38) 100%),
    linear-gradient(to bottom,rgba(40,24,8,.22),rgba(40,24,8,0) 22%,rgba(40,24,8,0) 78%,rgba(40,24,8,.28))}
@media (prefers-reduced-motion:reduce){.sd-plate{animation:none}.sd-plate.p1{opacity:1}}
